use am4::{airport::db::Airports,route::{db::DistanceMatrix,ticket::{PaxTicket,CargoTicket}},user::GameMode};
use serde_json::{Value,json};
fn main(){let ap=Airports::from_bytes(&include_bytes!("../vendor/am4/assets/airports-v2.bin").to_vec()).unwrap();let ds=DistanceMatrix::from_airports(ap.data());let mut rows:Vec<Value>=serde_json::from_str(include_str!("../web/fleet.json")).unwrap();for r in &mut rows{let a=ap.search(r["a"].as_str().unwrap()).unwrap();let b=ap.search(r["b"].as_str().unwrap()).unwrap();let km=ds.get_unchecked(a.idx,b.idx).get();let p=PaxTicket::from_optimal(km,GameMode::Realism);let c=CargoTicket::from_optimal(km,GameMode::Realism);r["tickets"]=if r["model"]=="A380-800F"{json!({"large":c.l,"heavy":c.h})}else{json!({"Y":p.y,"J":p.j,"F":p.f})};r["km"]=json!(km);}println!("{}",serde_json::to_string(&rows).unwrap())}
